import{_ as t,o as a,c as i,a3 as o}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"What is xclang","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"What is xclang | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/guide/what-is-xclang"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/guide/what-is-xclang"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/guide/what-is-xclang"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/guide/what-is-xclang"}]]},"headers":[],"relativePath":"xclang/guide/what-is-xclang.md","filePath":"en/xclang/guide/what-is-xclang.md","lastUpdated":1791227177000}'),n={name:"xclang/guide/what-is-xclang.md"};function s(r,e,l,h,c,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="what-is-xclang" tabindex="-1">What is xclang <a class="header-anchor" href="#what-is-xclang" aria-label="Permalink to &quot;What is xclang&quot;">​</a></h1><p>xclang is a clang toolchain for cross-compiling, the way rustup, cross-rs and cargo-zigbuild let Rust do it: one compiler for every target. One directory holds the compiler, the linker, the binary tools and, for six targets, the sysroot and the runtimes, so cross-compiling is a <code>--target</code> flag and nothing else:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=aarch64-w64-mingw32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.exe</span></span></code></pre></div><p>The common targets come with the toolchain; everything else (more targets, and the vendor SDKs that cannot be redistributed) is to be fetched when a build needs it. It is stock LLVM, with a few <a href="./../design/patches">patches</a> that are on their way upstream, built with PGO and ThinLTO for six hosts.</p><h2 id="what-is-in-it" tabindex="-1">What is in it <a class="header-anchor" href="#what-is-in-it" aria-label="Permalink to &quot;What is in it&quot;">​</a></h2><ul><li><strong>clang and lld</strong>, and the LLVM binary tools, as one program (<code>llvm</code>), linked statically against xclang&#39;s own libc++: 95 to 128 MB an archive.</li><li><strong>Six targets in every archive</strong>: Linux x64 and arm64 (glibc 2.17), Windows x64 and arm64 (MinGW-w64, UCRT), macOS arm64 and x64 (with Xcode&#39;s SDK, so from macOS hosts). Each has its sysroot, libc++, libc++abi, libunwind and compiler-rt, prebuilt, and a config file that points clang at them.</li><li><strong>Programs that run where they are copied</strong>: everything but the OS&#39;s own libraries is linked in (<a href="./../design/hermeticity">hermeticity</a>).</li><li><strong>A CMake package and a Bazel module</strong>: the toolchain for the host or any target, and <code>import std</code> built for the build.</li><li><strong>libclang</strong>, the static libraries the toolchain&#39;s clang was linked from (ThinLTO bitcode), and the option tables, for tools built on clang.</li></ul><h2 id="who-it-is-for" tabindex="-1">Who it is for <a class="header-anchor" href="#who-it-is-for" aria-label="Permalink to &quot;Who it is for&quot;">​</a></h2><p>People who want a toolchain they can pin, ship and reproduce, and binaries that run wherever they are copied:</p><ul><li><strong>Projects that ship programs</strong> to many machines: command-line tools, language servers, build tools, games&#39; tools. A Linux program runs on glibc 2.17 and later, a Windows one needs no redistributable, a macOS one no Homebrew.</li><li><strong>CI that builds for several targets</strong> from one kind of runner, with one compiler version for all of them.</li><li><strong>Teams that want one toolchain</strong> on every developer machine and in CI, pinned by version and digest, the same in CMake, Bazel and plain commands.</li><li><strong>C++20 modules</strong> with <code>import std</code>, in CMake and Bazel today.</li><li><strong>Tools on clang</strong>: libclang with PGO, the option tables.</li></ul><p>xclang is developed for <a href="https://github.com/clice-io/clice" target="_blank" rel="noreferrer">clice</a>, whose release builds are its first user; <a href="https://github.com/clice-io/catter" target="_blank" rel="noreferrer">catter</a> builds with it too, and xclang&#39;s CI builds <a href="https://github.com/clice-io/kotatsu" target="_blank" rel="noreferrer">kotatsu</a>&#39;s tests for Windows from Linux with its Bazel module and runs them on Windows.</p><h2 id="when-not-to-use-it" tabindex="-1">When not to use it <a class="header-anchor" href="#when-not-to-use-it" aria-label="Permalink to &quot;When not to use it&quot;">​</a></h2><p>xclang makes choices; where they do not fit, another toolchain is the better one:</p><ul><li><strong>You link C++ libraries built by another toolchain.</strong> xclang&#39;s C++ library is libc++, linked into every program. A C++ library from the system or a vendor, built with GCC&#39;s libstdc++ (a distribution&#39;s Qt or Boost) or with MSVC&#39;s STL, has another ABI: build C++ dependencies with xclang for the target (with CMake, Bazel, vcpkg&#39;s chain-loaded toolchain file, ...). C libraries are fine.</li><li><strong>You need the MSVC ABI.</strong> xclang&#39;s Windows targets are MinGW today; MSVC targets, against the user&#39;s MSVC and Windows SDK, are in research. For MSVC today, use clang-cl with Visual Studio.</li><li><strong>C++ objects cross shared libraries.</strong> Each shared library carries its own libc++; standard exceptions are caught across them only by <code>catch (...)</code> on Linux and macOS (<a href="./../design/hermeticity#one-libc-per-shared-object">one libc++ per shared object</a>). A plugin system with C++ interfaces wants a shared C++ runtime.</li><li><strong>Your target is not one of the six yet</strong>: musl, iOS, Android, WebAssembly, embedded, other Linux architectures. They are in the <a href="./../design/roadmap">roadmap</a>; today the NDK, wasi-sdk, zig cc or a GCC cross toolchain serve them.</li><li><strong>macOS from Linux or Windows.</strong> Not yet; xclang&#39;s macOS targets need Xcode&#39;s SDK on a Mac.</li><li><strong>You need OpenMP, MemorySanitizer, sanitizers on Windows</strong>, or clang-format, clang-tidy and clangd binaries: not included.</li><li><strong>You build conda-forge packages</strong>: use conda-forge&#39;s compilers, which integrate with its runtime packages; xclang deliberately does not.</li></ul><p><a href="./comparisons">Comparisons</a> puts xclang next to the toolchains people use for the same jobs, with what each does better.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="./quick-start">Quick start</a>: programs for every target, then a CMake project with <code>import std</code>.</li><li><a href="./why-xclang">Why xclang</a>: the case for it, with the evidence and the gaps.</li><li><a href="./install">Installing</a>.</li></ul>',16)])])}const u=t(n,[["render",s]]);export{p as __pageData,u as default};
